use crate::{archive,backups,error,files,safety,software::Software,Result,Server,Shared};
use std::path::{Path,PathBuf};
use tauri::State;
fn location(root:&Path,server:&Server,world:&str,dimension:&str)->Result<PathBuf>{crate::worlds::world_name(world)?;let (suffix,folder)=match dimension{"nether"=>("_nether","DIM-1"),"end"=>("_the_end","DIM1"),_=>return Err("Only Nether and End can be transferred".into())};let base=if matches!(server.software,Software::Paper|Software::Purpur){format!("{world}{suffix}")}else{world.into()};files::root_path(root,&format!("{base}/{folder}"))}
fn transfer(global:&Path,from:&Server,to:&Server,source_world:&str,target_world:&str,dimension:&str,moving:bool)->Result<()> {
    if from.version!=to.version{return Err("Dimension transfer requires identical Minecraft versions; version conversion is not performed".into());}
    let source_root=global.join("servers").join(&from.id);let target_root=global.join("servers").join(&to.id);let source=location(&source_root,from,source_world,dimension)?;let target=location(&target_root,to,target_world,dimension)?;
    if source==target||!source.is_dir(){return Err("Choose different source and destination dimensions; source data must exist".into());}
    let source_level=files::root_path(&source_root,&format!("{source_world}/level.dat"))?;let target_level=files::root_path(&target_root,&format!("{target_world}/level.dat"))?;if !source_level.is_file()||!target_level.is_file(){return Err("Both base worlds must already be generated".into());}
    let stage=archive::Stage::new(&global.join("cache/dimensions"))?;let work=stage.0.join("dimension");std::fs::create_dir(&work).map_err(error)?;
    for name in archive::tree(&source)?{let output=work.join(&name);std::fs::create_dir_all(output.parent().ok_or("Missing parent")?).map_err(error)?;std::fs::copy(source.join(name),output).map_err(error)?;}
    let source_trash=source_root.join(".minehost/dimension-trash");if moving{safety::reject_links(&source_trash)?;std::fs::create_dir_all(&source_trash).map_err(error)?;}
    backups::create(global,from,&source_root)?;if from.id!=to.id{backups::create(global,to,&target_root)?;}
    let parent=target.parent().ok_or("Missing dimension parent")?;safety::reject_links(parent)?;std::fs::create_dir_all(parent).map_err(error)?;
    if matches!(to.software,Software::Paper|Software::Purpur)&&!parent.join("level.dat").exists(){std::fs::copy(&target_level,parent.join("level.dat")).map_err(error)?;}
    let trash=target_root.join(".minehost/dimension-trash");safety::reject_links(&trash)?;std::fs::create_dir_all(&trash).map_err(error)?;let retained=trash.join(uuid::Uuid::new_v4().to_string());let existed=target.exists();if existed{std::fs::rename(&target,&retained).map_err(error)?;}
    if let Err(e)=std::fs::rename(&work,&target){if existed{std::fs::rename(&retained,&target).map_err(|r|format!("{e}; rollback: {r}; retained: {}",retained.display()))?;}return Err(error(e));}
    if moving{if let Err(e)=std::fs::rename(&source,source_trash.join(uuid::Uuid::new_v4().to_string())){std::fs::rename(&target,&work).map_err(error)?;if existed{std::fs::rename(&retained,&target).map_err(error)?;}return Err(error(e));}}Ok(())
}
#[derive(serde::Deserialize)]#[serde(rename_all="camelCase")]pub struct Transfer{source_world:String,target_id:String,target_world:String,dimension:String,moving:bool,confirmation:String}
#[tauri::command]pub async fn transfer_dimension(state:State<'_,Shared>,id:String,request:Transfer)->Result<()> {let shared=state.inner().clone();tauri::async_runtime::spawn_blocking(move||{let _first=crate::begin(&shared,&id)?;let _second=if id!=request.target_id{Some(crate::begin(&shared,&request.target_id)?)}else{None};let(global,from,to)={let inner=crate::lock(&shared)?;(inner.root.clone(),crate::load(&inner,&id)?,crate::load(&inner,&request.target_id)?)};if request.confirmation!=format!("{} -> {}",request.source_world,request.target_world){return Err("Confirm the exact source and target world names".into());}transfer(&global,&from,&to,&request.source_world,&request.target_world,&request.dimension,request.moving)}).await.map_err(error)?}
#[cfg(test)]mod tests{use super::*;fn server()->Server{Server{id:uuid::Uuid::new_v4().to_string(),name:"Test".into(),version:"1.21.1".into(),port:25565,ram_mb:2048,eula:false,installed:true,java_major:21,software:Software::Vanilla,loader_version:None}}#[test]fn transfers_vanilla_to_paper_and_preserves_replaced_dimension(){let root=archive::Stage::new(&std::env::temp_dir()).unwrap();let from=server();let mut to=server();to.software=Software::Paper;for server in [&from,&to]{let profile=root.0.join("servers").join(&server.id);std::fs::create_dir_all(profile.join("world")).unwrap();std::fs::write(profile.join("world/level.dat"),b"level").unwrap();}let source=root.0.join("servers").join(&from.id).join("world/DIM-1");std::fs::create_dir(&source).unwrap();std::fs::write(source.join("region.mca"),b"source").unwrap();let target=root.0.join("servers").join(&to.id).join("world_nether/DIM-1");std::fs::create_dir_all(&target).unwrap();std::fs::write(target.join("region.mca"),b"old").unwrap();transfer(&root.0,&from,&to,"world","world","nether",true).unwrap();assert_eq!(std::fs::read(target.join("region.mca")).unwrap(),b"source");assert!(!source.exists());assert!(root.0.join("servers").join(&from.id).join(".minehost/dimension-trash").is_dir());}}
